mapper.select:
SELECT COUNT(*)
  FROM bbs31_content
 WHERE 1=1
   AND bbs31_class_tree_id = #{classTreeId}
   AND CONCAT(bbs31_title, f_emp_kor_nm(bbs31_person_id)) ILIKE #{searchText}
   AND (
          (COALESCE(bbs31_hide_yn,'false') = 'false')
          OR
          (COALESCE(bbs31_hide_yn,'false') = 'true' AND bbs31_person_id = #{personId})
       )

SELECT COUNT(*)
  FROM bbs31_content
 WHERE bbs31_class_tree_id = #{classTreeId}
   AND bbs31_company_id = #{companyId}

SELECT COUNT(*)
  FROM bbs31_content
 WHERE bbs31_class_tree_id IN (
                                 SELECT bbs30_class_tree_id
                                   FROM bbs30_class_tree
                                  WHERE bbs30_parent_tree_id = #{parentTreeId}
                                    AND bbs30_company_id = #{companyId}
                              )
   AND bbs31_company_id = #{companyId}

mapper.update:
UPDATE bbs31_content
   SET bbs31_title    = #{title}
     , bbs31_content  = #{content}
     , bbs31_hide_yn  = CASE WHEN #{hideYn} THEN 'true' ELSE 'false' END
 WHERE bbs31_content_id = #{contentId}
   AND bbs31_company_id = #{companyId}

mapper.delete:
DELETE FROM bbs31_content
 WHERE bbs31_company_id = #{companyId}
   AND bbs31_content_id = #{contentId}
